import { cacheTag } from 'next/cache'

export interface Post {
  id: number
  title: string
  content: string
}

// Simple in-memory store standing in for a database. Stored on globalThis so
// it survives module reloads in dev.
const store = globalThis as typeof globalThis & { __posts?: Post[] }
store.__posts ??= []

export async function getPosts(): Promise<Post[]> {
  'use cache'
  cacheTag('posts')
  return store.__posts ?? []
}

export async function insertPost(title: string, content: string): Promise<Post> {
  const posts = store.__posts!
  const post: Post = { id: posts.length + 1, title, content }
  posts.push(post)
  return post
}

