'use server'

import { updateTag } from 'next/cache'
import { insertPost } from './data'

export async function createPost(formData: FormData) {
  const title = String(formData.get('title') ?? '')
  const content = String(formData.get('content') ?? '')

  await insertPost(title, content)

  // updateTag immediately expires the 'posts' cache entry: the next request
  // blocks until fresh data is fetched instead of serving stale content
  // (unlike revalidateTag('posts', 'max'), which is stale-while-revalidate).
  updateTag('posts')
}

